/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountFilterDrawer, type FilterDrawerOptions } from "../../components/filter-drawer/FilterDrawerEngine.js";
import type { MotionController } from "../../components/filter-drawer/motion-runtime";

export function FilterDrawer({ options, className }: { options?: FilterDrawerOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountFilterDrawer(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="filter-drawer" />;
}

